<script setup lang="ts">
import { mockBrands, mockFirms } from '~/data/mock/entities'
import { CASE_TYPE_LABELS } from '~/data/mock/cases'
import { entitySlug } from '~/utils/content'
const props = defineProps<{ kind: 'brand' | 'firm'; slug: string }>()
const entity = computed(() => (props.kind === 'brand' ? mockBrands : mockFirms).find(item => item.slug === props.slug))
if (!entity.value) throw createError({ statusCode:404, statusMessage:'档案不存在', fatal:true })
const cases = computed(() => [...(entity.value?.cases ?? [])].sort((a,b) => b.filedAt.localeCompare(a.filedAt)))
useSeoMeta({ title: () => `${entity.value?.name} · ${props.kind === 'brand' ? '品牌历史发案' : '律所介绍'}`, description: () => entity.value?.description })
</script>
<template><div v-if="entity" class="entity-detail"><PageContainer><nav class="entity-detail__crumb" aria-label="面包屑"><NuxtLink :to="kind === 'brand' ? '/brands' : '/faq/plaintiff-firms'">← 返回{{ kind === 'brand' ? '侵权品牌库' : '原告律所目录' }}</NuxtLink></nav><ContentColumns group="tro"><header class="entity-detail__header"><p>{{ kind === 'brand' ? '品牌档案 · BRAND PROFILE' : '代理律所 · LAW FIRM PROFILE' }}</p><h1>{{ entity.name }}</h1><p>{{ entity.description }}</p><div class="entity-detail__stats"><span><strong>{{ cases.length }}</strong> 条关联案件</span><span>{{ Array.from(new Set(cases.map(item => CASE_TYPE_LABELS[item.caseType]))).join(' / ') }}</span></div></header><section class="entity-detail__cases"><h2>{{ kind === 'brand' ? '该品牌历史发案' : '代理的历史案件' }}</h2><article v-for="record in cases" :key="record.id"><div><time :datetime="record.filedAt">{{ record.filedAt }}</time> · {{ record.state }} · {{ record.status }}</div><h3><NuxtLink :to="`/tro/cases/${record.slug}`">{{ record.caseNumber }} · {{ record.plaintiffBrand }}</NuxtLink></h3><p>{{ record.summary }}</p><p>代理律所：<NuxtLink :to="`/law-firms/${entitySlug(record.lawFirm)}`">{{ record.lawFirm }}</NuxtLink> · 品牌：<NuxtLink :to="`/brands/${entitySlug(record.plaintiffBrand)}`">{{ record.plaintiffBrand }}</NuxtLink></p><NuxtLink :to="`/tro/cases/${record.slug}`">查看完整案件 →</NuxtLink></article></section></ContentColumns></PageContainer></div></template>
<style scoped>
.entity-detail { padding:32px 0 64px; background:var(--color-bg-light); } .entity-detail__crumb { margin-bottom:24px; font-size:14px; } .entity-detail__header { padding:32px; border:1px solid var(--color-border); border-radius:12px; background:white; border-top:3px solid var(--color-primary); } .entity-detail__header > p:first-child { font-size:12px; color:var(--color-primary); } h1 { font-size:30px; margin:14px 0; } .entity-detail__header p { line-height:1.8; color:var(--color-text-muted); } .entity-detail__stats { display:flex; gap:24px; margin-top:24px; font-size:14px; } strong { font-size:26px; color:var(--color-primary); } .entity-detail__cases { margin-top:28px; } h2 { font-size:22px; margin-bottom:18px; } article { background:white; border:1px solid var(--color-border); border-radius:12px; padding:24px; margin-top:16px; } article div, article p { font-size:14px; color:var(--color-text-muted); line-height:1.8; } h3 { font-size:18px; margin:12px 0; } article > a { display:inline-block; margin-top:12px; font-size:14px; } @media(max-width:639px) { .entity-detail__header { padding:22px; } h1 { font-size:24px; } }
</style>
